"use client";

import { useTransition } from "react";
import { Plus } from "lucide-react";
import { addToCart } from "@/app/actions/cart";
import { useStoreUI } from "./StoreUI";

/** One-tap "Add" on product cards; animates the card image into the cart. */
export function QuickAdd({ productId, name }: { productId: string; name: string }) {
  const { toast, flyToCart, openCart } = useStoreUI();
  const [pending, start] = useTransition();
  return (
    <button
      disabled={pending}
      onClick={(e) => {
        e.preventDefault();
        const card = (e.currentTarget as HTMLElement).closest("[data-product-card]")?.querySelector<HTMLElement>("[data-product-image]") ?? null;
        start(async () => {
          const res = await addToCart({ productId, quantity: 1 });
          if (!res.ok) return toast(res.error ?? "Could not add to cart", "error");
          flyToCart(card);
          toast(`Added “${name}” to cart`, "success");
          setTimeout(openCart, 650);
        });
      }}
      className="press flex items-center gap-1 rounded-full bg-ink px-3 py-1.5 text-xs font-semibold text-white shadow-md hover:bg-maroon disabled:opacity-60"
      aria-label={`Add ${name} to cart`}
    >
      <Plus className="h-3.5 w-3.5" aria-hidden /> {pending ? "Adding…" : "Add"}
    </button>
  );
}
