"use client";

import { useState } from "react";
import { Heart } from "lucide-react";
import { useStoreUI } from "./StoreUI";
import { cn } from "@/lib/utils";

export function WishlistButton({ productId, name, variant = "icon" }: { productId: string; name: string; variant?: "icon" | "full" }) {
  const { wishlist, toggleWish } = useStoreUI();
  const [pop, setPop] = useState(0);
  const saved = wishlist.has(productId);
  const onClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setPop((p) => p + 1);
    void toggleWish(productId, name);
  };
  if (variant === "full") {
    return (
      <button onClick={onClick} aria-pressed={saved} className="btn-outline press w-full text-sm">
        <Heart key={pop} className={cn("h-4 w-4", saved && "fill-maroon text-maroon", pop > 0 && "animate-heart-pop")} aria-hidden />
        {saved ? "Saved to wishlist" : "Add to wishlist"}
      </button>
    );
  }
  return (
    <button
      onClick={onClick}
      aria-pressed={saved}
      aria-label={saved ? `Remove ${name} from wishlist` : `Save ${name} to wishlist`}
      className="press flex h-9 w-9 items-center justify-center rounded-full bg-white/90 shadow-sm ring-1 ring-line backdrop-blur transition hover:bg-white"
    >
      <Heart key={pop} className={cn("h-[18px] w-[18px] transition-colors", saved ? "fill-maroon text-maroon" : "text-ink-soft", pop > 0 && "animate-heart-pop")} aria-hidden />
    </button>
  );
}
